import{_ as o,o as r,c as n,ah as s}from"./chunks/framework.DjU4PSOm.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"지각의 구분: 인상과 관념","slug":"지각의-구분-인상과-관념","link":"#지각의-구분-인상과-관념","children":[]},{"level":2,"title":"인상의 모사","slug":"인상의-모사","link":"#인상의-모사","children":[]},{"level":2,"title":"흄의 포크 (회의주의)","slug":"흄의-포크-회의주의","link":"#흄의-포크-회의주의","children":[]},{"level":2,"title":"인과 관계 분석","slug":"인과-관계-분석","link":"#인과-관계-분석","children":[]},{"level":2,"title":"규칙성 인과이론에 대한 비판","slug":"규칙성-인과이론에-대한-비판","link":"#규칙성-인과이론에-대한-비판","children":[]}],"relativePath":"philosophy/Epistemology/05. 흄.md","filePath":"philosophy/Epistemology/05. 흄.md"}'),l={name:"philosophy/Epistemology/05. 흄.md"};function e(a,t,i,g,p,h){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="지각의-구분-인상과-관념" tabindex="-1">지각의 구분: 인상과 관념 <a class="header-anchor" href="#지각의-구분-인상과-관념" aria-label="Permalink to &quot;지각의 구분: 인상과 관념&quot;">​</a></h2><p>흄은 로크의 &#39;관념&#39;을 <strong>지각(perception)</strong>이라는 상위 개념으로 부르고, 이를 <strong>인상(impression)</strong>과 <strong>관념(idea)</strong>으로 구분함.</p><ul><li>생생하면 → <strong>감각 인상 / 반성 인상</strong></li><li>생생하지 않으면(인상의 희미한 사본) → <strong>감각 관념 / 반성 관념</strong></li></ul><p>쾌와 불쾌는 오직 <strong>감각 인상</strong>에서만 일어남. 이에 대해 생겨나는 정서적 반응·정념 등이 <strong>반성 인상</strong>임 — 로크와 달리, 이미 지각된 것을 다시 지각함으로써 &#39;반성인상&#39;이 생기는 것이 아니라, 그 자체로 처음부터 하나의 지각(인상)으로 발생하는 것.</p><h2 id="인상의-모사" tabindex="-1">인상의 모사 <a class="header-anchor" href="#인상의-모사" aria-label="Permalink to &quot;인상의 모사&quot;">​</a></h2><ul><li><strong>기억</strong>: 인상을 충실히 재현 — 원본에 얽매이고 구속됨</li><li><strong>상상</strong>: 원본에 얽매이지 않고 자유롭게 변형 → <strong>복합관념</strong>을 만들어냄</li></ul><p>완전히 자유로운 상상이라면 그보다 이해하기 어려운 것이 없음 — 그렇다면 상상은 어떤 원리에 따라 작동하는가? (→ 관념들의 연합 원리로 이어짐)</p><p>인식은 결국 <strong>관념들 사이의 관계</strong>에 대한 인식.</p><h2 id="흄의-포크-회의주의" tabindex="-1">흄의 포크 (회의주의) <a class="header-anchor" href="#흄의-포크-회의주의" aria-label="Permalink to &quot;흄의 포크 (회의주의)&quot;">​</a></h2><p>우리는 인식주체의 관념·지각이 세계를 어떻게 인식하는지 고민할 수 있을 뿐, 세계에 대한 지식(사실의 문제, 관념에 의존하지 않는 관계)은 인식주체의 관념·지각까지만 인지 가능함.</p><p>이러한 회의주의는 기존의 인식 체계를 완전히 무너뜨리려는 것이 아니라, <strong>한계를 인식</strong>하고 세계에 대한 지식이 (필연적이 아닌) <strong>개연적인 지식</strong>임을 받아들이자는 것 — 이를 통해 오히려 세계 속에서 더 잘 살아갈 수 있음.</p><h2 id="인과-관계-분석" tabindex="-1">인과 관계 분석 <a class="header-anchor" href="#인과-관계-분석" aria-label="Permalink to &quot;인과 관계 분석&quot;">​</a></h2><p>인과관계로 여겨지는 것의 구성 요소:</p><ol><li><strong>공간적 인접성</strong>: 인접한 공간에서 일어남</li><li><strong>시간적 계기성</strong>: 원인이 결과에 앞섬</li><li><strong>필연적 연관성</strong>: 원인이 생기면 결과가 반드시 일어난다는 것 — <strong>그러나 감각은 이 필연성을 제시해줄 수 없음</strong></li></ol><p><strong>필연적 연관성에 대한 회의</strong>: a, b 사이의 무수히 많은 과거 인상을 다 가지고 있어도, 그로부터 미래에도 반드시 그럴 것이라는 것을 논리적으로 도출할 수 없음. 일반적으로 그렇게 일어난다고 추측할 수는 있지만, 아닐 가능성은 항상 남아 있음 — &#39;must(반드시)&#39;로 받아들일 근거가 없음.</p><p><strong>습관과 기대</strong>: 항상적 결합(constant conjunction)을 반복 경험하다 보면 기대를 하게 되고, 이 기대가 상상력에 영향을 미침 → <strong>인과 관념은 습관적 기대감에 따른 상상력의 연합 작용</strong>일 뿐 — a와 b가 필연적으로 연결되어 있다고 &#39;상상&#39;하는 것.</p><p>대상에 대한 감각경험으로 인상이 주어지지만, 그 감각경험이 인과적인 힘에 의해 발생했다는 것을 감각경험 자체가 필연적으로 보장해주지는 못함 → 외부세계에 대한 회의주의 (우리 인식의 한계를 인정하자는 입장).</p><h2 id="규칙성-인과이론에-대한-비판" tabindex="-1">규칙성 인과이론에 대한 비판 <a class="header-anchor" href="#규칙성-인과이론에-대한-비판" aria-label="Permalink to &quot;규칙성 인과이론에 대한 비판&quot;">​</a></h2><p>규칙성 인과이론: &quot;원인이 일어나면 규칙적으로 결과가 일어난다.&quot;</p><p><strong>토마스 리드의 공통원인 문제</strong>: 원인 a가 결과 b1, b2를 모두 야기한다면, 규칙성만으로는 b1과 b2 사이에도 인과관계가 있다고 오인될 수 있음 — 예: 낮과 밤은 지구의 자전이라는 <strong>공통원인</strong> 때문이지만, 규칙성만 보면 낮과 밤이 서로의 원인·결과인 것처럼 여겨질 수 있음. 이는 규칙적 결합만으로 인과를 정의하는 이론의 한계를 보여줌.</p>',20)])])}const u=o(l,[["render",e]]);export{d as __pageData,u as default};
